/*
 * Coinverge - ESP32 Coin Exchange / Money Changer Firmware
 *
 * Rebuilt from firmware binary (coinverge_backup.bin)
 * Original build: Arduino + ESP-IDF v4.4.7 (Mar 5 2024)
 * Target board : ESP32 (Arduino ESP32 core v2.0.15)
 *
 * Architecture:
 *   - loopTask   : Arduino main loop (coin acceptor polling, exchange trigger)
 *   - uart_event_task : FreeRTOS task reading bill acceptor / serial device via UART2
 *
 * Extracted function names from binary:
 *   openhop, closehop, exchangeMoney, exchangeTerminate
 *
 * Serial debug output patterns confirmed in binary:
 *   "SYSTEM START"
 *   "Total Money: %d"
 *   "Count %u"
 *   "Split %d > FData : %s"
 *   "D[%d] :"
 *   " L:%d"
 *   "exchangeMoney: "
 *   "ERROR: NO EXCHANGE"
 */

#include <Arduino.h>
#include "driver/uart.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/queue.h"

// ─────────────────────────────────────────────────────────────
//  Hardware pin configuration (adjust to match your PCB)
// ─────────────────────────────────────────────────────────────
// Hopper / coin dispenser control pins
#define HOP_PIN        18   // HIGH = open hopper motor relay

// Bill acceptor UART (UART2)
#define UART_BA        UART_NUM_2
#define UART_BA_TX     17
#define UART_BA_RX     16
#define UART_BA_BAUD   9600
#define UART_BUF_SIZE  256

// Coin acceptor pulse input (optional — if NV-series coin mech)
#define COIN_PULSE_PIN 19

// Coin denominations supported (in local currency units, e.g. centavos)
// Adjust to your market: 1, 5, 10, 25 pesos / PHP coins
#define DENOM_COUNT    4
const int COIN_DENOMINATIONS[DENOM_COUNT] = { 1, 5, 10, 25 };

// ─────────────────────────────────────────────────────────────
//  State
// ─────────────────────────────────────────────────────────────
static QueueHandle_t uart_event_queue;
static volatile int  totalMoney   = 0;   // cumulative inserted amount
static volatile bool exchangeReady = false;

// ─────────────────────────────────────────────────────────────
//  Forward declarations
// ─────────────────────────────────────────────────────────────
void openhop();
void closehop();
bool exchangeMoney(int amount);
void exchangeTerminate();
void splitDenominations(int amount, int* outCounts);
void uart_event_task(void* pvParameters);
void printDenominationData(int amount, int* counts);

// ─────────────────────────────────────────────────────────────
//  setup()
// ─────────────────────────────────────────────────────────────
void setup() {
    Serial.begin(115200);
    Serial.println("SYSTEM START");

    // Hopper pin
    pinMode(HOP_PIN, OUTPUT);
    closehop();

    // Coin acceptor pulse pin
    pinMode(COIN_PULSE_PIN, INPUT_PULLUP);

    // UART2 — bill acceptor
    uart_config_t uart_config = {
        .baud_rate  = UART_BA_BAUD,
        .data_bits  = UART_DATA_8_BITS,
        .parity     = UART_PARITY_DISABLE,
        .stop_bits  = UART_STOP_BITS_1,
        .flow_ctrl  = UART_HW_FLOWCTRL_DISABLE,
        .rx_flow_ctrl_thresh = 122,
        .source_clk = UART_SCLK_APB,
    };

    uart_driver_install(UART_BA, UART_BUF_SIZE * 2, UART_BUF_SIZE * 2, 20, &uart_event_queue, 0);
    uart_param_config(UART_BA, &uart_config);
    uart_set_pin(UART_BA, UART_BA_TX, UART_BA_RX, UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE);

    // Start UART event task (mirrors uart_event_task in binary)
    xTaskCreate(uart_event_task, "uart_event_task", 4096, NULL, 12, NULL);

    Serial.printf("Total Money: %d\n", totalMoney);
}

// ─────────────────────────────────────────────────────────────
//  loop()  — Arduino loopTask
// ─────────────────────────────────────────────────────────────
void loop() {
    // Poll for coin pulses from coin acceptor
    static unsigned long lastPulse = 0;
    static unsigned int  pulseCount = 0;
    static bool          inPulseWindow = false;

    if (digitalRead(COIN_PULSE_PIN) == LOW) {
        if (millis() - lastPulse > 50) {   // debounce
            pulseCount++;
            lastPulse = millis();
            inPulseWindow = true;
        }
    }

    // After pulse burst ends, decode denomination
    if (inPulseWindow && (millis() - lastPulse > 300)) {
        inPulseWindow = false;
        if (pulseCount > 0) {
            // Map pulse count to denomination value
            // Common NV11 / JCM coding:  1 pulse=1, 5 pulses=5, 10 pulses=10, 25 pulses=25
            // Or simple: each pulse = 1 peso unit
            int coinValue = pulseCount;
            totalMoney += coinValue;
            Serial.printf("Total Money: %d\n", totalMoney);
            Serial.printf("Count %u\n", pulseCount);
            pulseCount = 0;
        }
    }

    // Trigger exchange if money is available
    if (exchangeReady && totalMoney > 0) {
        exchangeReady = false;
        if (!exchangeMoney(totalMoney)) {
            Serial.println("ERROR: NO EXCHANGE");
        }
    }

    vTaskDelay(10 / portTICK_PERIOD_MS);
}

// ─────────────────────────────────────────────────────────────
//  openhop() — activate hopper / coin dispenser
// ─────────────────────────────────────────────────────────────
void openhop() {
    digitalWrite(HOP_PIN, HIGH);
    Serial.println("openhop");
}

// ─────────────────────────────────────────────────────────────
//  closehop() — stop hopper / coin dispenser
// ─────────────────────────────────────────────────────────────
void closehop() {
    digitalWrite(HOP_PIN, LOW);
    Serial.println("closehop");
}

// ─────────────────────────────────────────────────────────────
//  exchangeMoney(amount) — main exchange logic
//   Returns true  on success
//   Returns false if insufficient coins / error
// ─────────────────────────────────────────────────────────────
bool exchangeMoney(int amount) {
    Serial.printf("exchangeMoney: %d\n", amount);

    if (amount <= 0) {
        Serial.println("ERROR: NO EXCHANGE");
        return false;
    }

    int counts[DENOM_COUNT] = {0};
    splitDenominations(amount, counts);

    // Print denomination breakdown in original firmware format
    printDenominationData(amount, counts);

    // Dispense coins
    openhop();

    // TODO: implement real dispense counting via hopper opto-sensor feedback
    // For now use a timed approximation (replace with sensor loop)
    int totalCoins = 0;
    for (int i = 0; i < DENOM_COUNT; i++) totalCoins += counts[i];
    int dispenseMs = totalCoins * 300;  // ~300ms per coin, tune to your hopper
    delay(dispenseMs);

    closehop();
    exchangeTerminate();
    return true;
}

// ─────────────────────────────────────────────────────────────
//  exchangeTerminate() — end transaction, reset totalMoney
// ─────────────────────────────────────────────────────────────
void exchangeTerminate() {
    Serial.println("exchangeTerminate");
    totalMoney  = 0;
    Serial.printf("Total Money: %d\n", totalMoney);
}

// ─────────────────────────────────────────────────────────────
//  splitDenominations(amount, outCounts[])
//   Greedy algorithm — largest denomination first
//   Fills outCounts[i] with number of COIN_DENOMINATIONS[i] to dispense
// ─────────────────────────────────────────────────────────────
void splitDenominations(int amount, int* outCounts) {
    int remaining = amount;
    // Walk from largest to smallest denomination
    for (int i = DENOM_COUNT - 1; i >= 0; i--) {
        outCounts[i] = remaining / COIN_DENOMINATIONS[i];
        remaining   -= outCounts[i] * COIN_DENOMINATIONS[i];
    }
    // remaining should be 0 if denominations can exactly make amount
}

// ─────────────────────────────────────────────────────────────
//  printDenominationData()
//   Reproduces original firmware debug output:
//     "Split %d > FData : %s"
//     "D[%d] :  L:%d"
// ─────────────────────────────────────────────────────────────
void printDenominationData(int amount, int* counts) {
    // Build FData string like "1x5,2x10,1x25" etc.
    char fdata[64] = {0};
    char tmp[16];
    bool first = true;
    for (int i = 0; i < DENOM_COUNT; i++) {
        if (counts[i] > 0) {
            if (!first) strcat(fdata, ",");
            snprintf(tmp, sizeof(tmp), "%dx%d", counts[i], COIN_DENOMINATIONS[i]);
            strcat(fdata, tmp);
            first = false;
        }
    }

    Serial.printf("Split %d > FData : %s\n", amount, fdata);

    // Print each denomination slot
    for (int i = 0; i < DENOM_COUNT; i++) {
        Serial.printf("D[%d] :\n", i);
        Serial.printf(" L:%d\n", counts[i]);
    }
}

// ─────────────────────────────────────────────────────────────
//  uart_event_task — FreeRTOS task
//   Monitors bill acceptor on UART2.
//   On receiving a valid bill signal, adds bill value to totalMoney
//   and sets exchangeReady flag.
//
//   Bill acceptor protocol:
//   Modify parseAcceptorByte() to match your hardware
//   (common: Cashcode, JCM, BillTo, ICT, etc.)
// ─────────────────────────────────────────────────────────────
void uart_event_task(void* pvParameters) {
    uart_event_t event;
    uint8_t      buf[UART_BUF_SIZE];

    for (;;) {
        if (xQueueReceive(uart_event_queue, (void*)&event, portMAX_DELAY)) {
            switch (event.type) {

                case UART_DATA: {
                    int len = uart_read_bytes(UART_BA, buf, event.size, portMAX_DELAY);
                    if (len > 0) {
                        // Parse bill acceptor bytes
                        // Common Cashcode SSP / parallel protocol:
                        //   byte 0 = status, byte 1 = denomination code
                        for (int i = 0; i < len; i++) {
                            int billValue = parseAcceptorByte(buf[i]);
                            if (billValue > 0) {
                                totalMoney += billValue;
                                exchangeReady = true;
                                Serial.printf("Total Money: %d\n", totalMoney);
                            }
                        }
                    }
                    break;
                }

                case UART_FIFO_OVF:
                    uart_flush_input(UART_BA);
                    xQueueReset(uart_event_queue);
                    break;

                case UART_BUFFER_FULL:
                    uart_flush_input(UART_BA);
                    xQueueReset(uart_event_queue);
                    break;

                case UART_BREAK:
                case UART_PARITY_ERR:
                case UART_FRAME_ERR:
                    break;

                default:
                    break;
            }
        }
    }
    vTaskDelete(NULL);
}

// ─────────────────────────────────────────────────────────────
//  parseAcceptorByte(byte)
//   Translate a raw byte from the bill acceptor into a currency value.
//   This is the most hardware-specific part — customize for your device.
//
//   Example mapping (generic parallel / pulse):
//     0x01 = 20 peso bill
//     0x02 = 50 peso bill
//     0x03 = 100 peso bill
//     0x04 = 500 peso bill
//     0x05 = 1000 peso bill
// ─────────────────────────────────────────────────────────────
int parseAcceptorByte(uint8_t byte) {
    switch (byte) {
        case 0x01: return 20;
        case 0x02: return 50;
        case 0x03: return 100;
        case 0x04: return 500;
        case 0x05: return 1000;
        default:   return 0;
    }
}

