}

// ─────────────────────────────────────────────────────────────
//  exchangeTerminate() — end transaction, reset totalMoney
// ─────────────────────────────────────────────────────────────
void exchangeTerminate() {
    Serial.println("exchangeTerminate");
    totalMoney  = 0;
