#define HOP_SENSOR_PIN      -1      // -1 = not connected / not used
                                    // Set to actual GPIO if sensor is wired

// Timeout waiting for each coin to be sensed (ms). Only used if sensor is wired.
#define HOP_COIN_TIMEOUT_MS 800

// Fallback: ms per coin when no sensor is available (tune to your hopper speed)
#define HOP_MS_PER_COIN     350

// -----------------------------------------------------------------------------
//  COIN ACCEPTOR
