// -----------------------------------------------------------------------------
#define COIN_PIN            19      // GPIO receiving coin acceptor pulses
#define COIN_DEBOUNCE_MS    50      // Ignore bounces shorter than this
#define COIN_WINDOW_MS      400     // Wait this long after last pulse before decoding

