    // { pulse_count, peso_value }
    {  1,   1  },
    {  2,   5  },   // TODO: verify on actual hardware
    {  3,  10  },   // TODO: verify on actual hardware
    {  4,  25  },   // TODO: verify on actual hardware
    {  5,   0  },   // 0 = unknown / ignore
