//  TODO: identify the bill acceptor brand on the PCB (label, model sticker).
//        Then uncomment the matching PROTOCOL line below.
// -----------------------------------------------------------------------------
#define BILL_UART_PORT      2       // Use UART2
#define BILL_UART_TX_PIN    17      // ESP32 TX → acceptor RX
#define BILL_UART_RX_PIN    16      // ESP32 RX ← acceptor TX
#define BILL_UART_BAUD      9600    // Most acceptors: 9600 or 4800

// Bill acceptor protocol — uncomment ONE that matches your hardware:
#define BILL_PROTOCOL_PULSE     1   // Simple pulse (1 pulse per bill, value from width)
// #define BILL_PROTOCOL_PARALLEL  1   // Parallel BCD (4-bit denomination code)
// #define BILL_PROTOCOL_SSP       1   // Innovative Technology SSP (CPI NV-series)
// #define BILL_PROTOCOL_CASHCODE  1   // Cashcode SM / SMD

// Byte → bill value mapping (used by PULSE and generic serial protocols)
// TODO: sniff the actual bytes your acceptor sends per bill denomination.
//       Connect a USB-UART adapter between the acceptor and a PC, insert bills,
//       and record what bytes come out. Fill the table below.
#define BILL_TABLE_SIZE  5
const int BILL_BYTE_TABLE[BILL_TABLE_SIZE][2] = {
    // { byte_value, peso_value }
    { 0x01,   20   },   // TODO: confirm
    { 0x02,   50   },   // TODO: confirm
    { 0x03,  100   },   // TODO: confirm
    { 0x04,  500   },   // TODO: confirm
    { 0x05, 1000   },   // TODO: confirm
};

// -----------------------------------------------------------------------------
//  COIN DENOMINATIONS AVAILABLE IN HOPPER
//  List every denomination of coins loaded in the machine, smallest first.
//  The split algorithm will try to use the largest coins first.
// -----------------------------------------------------------------------------
#define DENOM_COUNT  4
const int DENOMINATIONS[DENOM_COUNT] = { 1, 5, 10, 25 };

// Maximum coins per denomination the hopper can hold at once.
// Used to prevent over-dispensing when hopper is low.
// Set to 0 to disable this check.
#define MAX_COINS_PER_DENOM  200

// -----------------------------------------------------------------------------
//  ACCEPTED BILL DENOMINATIONS
