 *
 *  Debug strings extracted from binary:
 *    "SYSTEM START"
 *    "Total Money: %d"
 *    "Count %u"
 *    "Split %d > FData : %s"
 *    "D[%d] :"  /  " L:%d"
 *    "exchangeMoney: "
 *    "ERROR: NO EXCHANGE"
 *    "exchangeTerminate"
 *
 *  FreeRTOS tasks in binary:
 *    loopTask        (Arduino main loop)
 *    uart_event_task (bill acceptor UART handler)
 *    IDLE0, IDLE1, ipc0, ipc1, esp_timer (ESP-IDF system tasks)
 *
 *  Student instructions:
 *    1. Open config.h and read all the TODO comments
 *    2. Keep DEBUG_MODE 1 first — test via Serial Monitor at 115200 baud
 *    3. Type commands in Serial Monitor to simulate hardware:
 *         BILL 100     → simulate inserting ₱100 bill
 *         COIN 10      → simulate inserting ₱10 coin
 *         STATUS       → print current state
 *         EXCHANGE     → manually trigger exchange
 *         RESET        → reset totals
 *    4. Once behavior is confirmed, probe real PCB for pins, update config.h,
 *       set DEBUG_MODE 0, and flash to the device.
 * ============================================================================
 */

#include <Arduino.h>
#include "config.h"
#include "driver/uart.h"
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/queue.h"

// ============================================================================
//  INTERNAL STATE
// ============================================================================

static QueueHandle_t  g_uart_queue;          // UART2 event queue
static volatile int   g_totalMoney    = 0;   // running total inserted (pesos)
static volatile bool  g_exchangeReady = false;
static volatile bool  g_hopperRunning = false;

// Coin inventory (decremented as coins are dispensed)
static int g_coinStock[DENOM_COUNT];

// ============================================================================
//  FORWARD DECLARATIONS
// ============================================================================

// Core functions (names from binary)
void openhop();
void closehop();
bool exchangeMoney(int amount);
void exchangeTerminate();

// Helpers
void     splitDenominations(int amount, int* outCounts);
void     printDenominationData(int amount, int* counts);
bool     canMakeChange(int amount);
int      lookupBillValue(uint8_t byte);
int      lookupCoinValue(int pulses);

// Tasks
void uart_event_task(void* pvParameters);

// Debug mode
#if DEBUG_MODE
void debugConsole();
void debugSimulateBill(int value);
void debugSimulateCoin(int value);
#endif

// ============================================================================
//  setup()
// ============================================================================

void setup() {
    Serial.begin(115200);
    delay(200);

    Serial.println();
    Serial.println("SYSTEM START");
    Serial.printf("Coinverge v1.0 | Build: Mar  5 2024 | IDF: v4.4.7\n");

#if DEBUG_MODE
    Serial.println("[DEBUG MODE] Hardware GPIO disabled. Use Serial commands.");
    Serial.println("Commands: BILL <amount>  COIN <amount>  STATUS  EXCHANGE  RESET");
#else
    // ── Hopper ──────────────────────────────────────────────
    pinMode(HOP_PIN, OUTPUT);
    digitalWrite(HOP_PIN, !HOP_ACTIVE);  // ensure hopper is OFF at boot

    // ── Hopper opto-sensor ───────────────────────────────────
    if (HOP_SENSOR_PIN >= 0) {
        pinMode(HOP_SENSOR_PIN, INPUT_PULLUP);
    }

    // ── Coin acceptor ────────────────────────────────────────
    pinMode(COIN_PIN, INPUT_PULLUP);

    // ── Bill acceptor UART ───────────────────────────────────
    uart_config_t uart_cfg = {
        .baud_rate           = BILL_UART_BAUD,
        .data_bits           = UART_DATA_8_BITS,
        .parity              = UART_PARITY_DISABLE,
        .stop_bits           = UART_STOP_BITS_1,
        .flow_ctrl           = UART_HW_FLOWCTRL_DISABLE,
        .rx_flow_ctrl_thresh = 122,
        .source_clk          = UART_SCLK_APB,
    };
    uart_driver_install(BILL_UART_PORT, 512, 512, 20, &g_uart_queue, 0);
    uart_param_config(BILL_UART_PORT, &uart_cfg);
    uart_set_pin(BILL_UART_PORT,
                 BILL_UART_TX_PIN, BILL_UART_RX_PIN,
                 UART_PIN_NO_CHANGE, UART_PIN_NO_CHANGE);

    // Start UART event task (name confirmed in binary)
    xTaskCreate(uart_event_task, "uart_event_task", 4096, NULL, 12, NULL);
#endif

    // Init coin stock to maximum
    for (int i = 0; i < DENOM_COUNT; i++) {
        g_coinStock[i] = MAX_COINS_PER_DENOM;
    }

    Serial.printf("Total Money: %d\n", g_totalMoney);
    Serial.println("Ready.");
}

// ============================================================================
//  loop()  — Arduino loopTask (name confirmed in binary)
// ============================================================================

void loop() {
#if DEBUG_MODE
    // ── Debug: read Serial commands ──────────────────────────
    debugConsole();
#else
    // ── Real hardware: poll coin acceptor ────────────────────
    static unsigned long lastPulseMs  = 0;
    static unsigned int  pulseCount   = 0;
    static bool          inWindow     = false;

    if (digitalRead(COIN_PIN) == LOW) {
        unsigned long now = millis();
        if (now - lastPulseMs > COIN_DEBOUNCE_MS) {
            pulseCount++;
            lastPulseMs = now;
            inWindow    = true;
        }
    }

    // Pulse window expired → decode denomination
    if (inWindow && (millis() - lastPulseMs > COIN_WINDOW_MS)) {
        inWindow = false;
        int value = lookupCoinValue(pulseCount);
        Serial.printf("Count %u\n", pulseCount);
        pulseCount = 0;

        if (value > 0) {
            g_totalMoney += value;
            Serial.printf("Total Money: %d\n", g_totalMoney);
        } else {
            Serial.println("[WARN] Unknown coin pulse count — ignored");
        }
    }
#endif

    // ── Exchange trigger ─────────────────────────────────────
    if (g_exchangeReady && g_totalMoney > 0) {
        g_exchangeReady = false;
        if (!exchangeMoney(g_totalMoney)) {
            Serial.println("ERROR: NO EXCHANGE");
        }
    }

    vTaskDelay(10 / portTICK_PERIOD_MS);
}

// ============================================================================
//  openhop() — activate hopper relay
//  Name confirmed in binary string table at 0x00010180
// ============================================================================

void openhop() {
    Serial.println("openhop");
    g_hopperRunning = true;
#if !DEBUG_MODE
    digitalWrite(HOP_PIN, HOP_ACTIVE);
#endif
}

// ============================================================================
//  closehop() — deactivate hopper relay
//  Name confirmed in binary string table at 0x00010188
// ============================================================================

void closehop() {
    Serial.println("closehop");
    g_hopperRunning = false;
#if !DEBUG_MODE
    digitalWrite(HOP_PIN, !HOP_ACTIVE);
#endif
}

// ============================================================================
//  exchangeMoney(amount) — main exchange logic
//  Name + format string "exchangeMoney: " confirmed in binary at 0x0001019f
// ============================================================================

bool exchangeMoney(int amount) {
    Serial.printf("exchangeMoney: %d\n", amount);

    // Basic guard
    if (amount <= 0) {
        Serial.println("ERROR: NO EXCHANGE");
        return false;
    }
    if (amount < MIN_BILL_VALUE || amount > MAX_BILL_VALUE) {
        Serial.printf("[WARN] Amount %d outside accepted range (%d-%d)\n",
                      amount, MIN_BILL_VALUE, MAX_BILL_VALUE);
        Serial.println("ERROR: NO EXCHANGE");
        return false;
    }

    // Check we have enough coins
    if (!canMakeChange(amount)) {
        Serial.println("ERROR: NO EXCHANGE");
        return false;
    }

    // Calculate split
    int counts[DENOM_COUNT] = {0};
    splitDenominations(amount, counts);
    printDenominationData(amount, counts);

    // ── Dispense ─────────────────────────────────────────────
    openhop();

#if DEBUG_MODE
    // Simulate dispensing time
    int totalCoins = 0;
    for (int i = 0; i < DENOM_COUNT; i++) totalCoins += counts[i];
    Serial.printf("[DEBUG] Dispensing %d coins (simulated %d ms)\n",
                  totalCoins, totalCoins * HOP_MS_PER_COIN);
    delay(min(totalCoins * HOP_MS_PER_COIN, 3000));

#else
    if (HOP_SENSOR_PIN >= 0) {
        // ── Sensor-guided dispensing ─────────────────────────
        // Walk denominations largest-first, count each coin via opto sensor
        for (int i = DENOM_COUNT - 1; i >= 0; i--) {
            int need = counts[i];
            if (need == 0) continue;

            Serial.printf("[HOP] Dispensing %d x ₱%d\n", need, DENOMINATIONS[i]);

            for (int c = 0; c < need; c++) {
                // Wait for one coin pulse from sensor
                unsigned long start = millis();
                bool sensed = false;
                while (millis() - start < HOP_COIN_TIMEOUT_MS) {
                    if (digitalRead(HOP_SENSOR_PIN) == LOW) {
                        delay(20);  // debounce
                        while (digitalRead(HOP_SENSOR_PIN) == LOW);  // wait release
                        sensed = true;
                        break;
                    }
                    vTaskDelay(5 / portTICK_PERIOD_MS);
                }
                if (!sensed) {
                    Serial.printf("[ERROR] Hopper sensor timeout on coin %d/%d denom ₱%d\n",
                                  c + 1, need, DENOMINATIONS[i]);
                    closehop();
                    exchangeTerminate();
                    return false;
                }
                g_coinStock[i]--;
            }
        }
    } else {
        // ── Timed dispensing fallback ─────────────────────────
        int totalCoins = 0;
        for (int i = 0; i < DENOM_COUNT; i++) {
            totalCoins += counts[i];
            g_coinStock[i] -= counts[i];
        }
        delay(totalCoins * HOP_MS_PER_COIN);
    }
#endif

    closehop();
    exchangeTerminate();
    return true;
}

// ============================================================================
//  exchangeTerminate() — end transaction
//  Name confirmed in binary at 0x000101c2
// ============================================================================

void exchangeTerminate() {
    Serial.println("exchangeTerminate");
    g_totalMoney    = 0;
    g_exchangeReady = false;
    Serial.printf("Total Money: %d\n", g_totalMoney);
}

// ============================================================================
//  splitDenominations() — greedy coin-split algorithm
//  Derived from "Split %d > FData : %s" format string in binary at 0x00010154
// ============================================================================

void splitDenominations(int amount, int* outCounts) {
    int remaining = amount;
    for (int i = DENOM_COUNT - 1; i >= 0; i--) {
        outCounts[i] = remaining / DENOMINATIONS[i];
        // Cap to available stock
        if (MAX_COINS_PER_DENOM > 0) {
            outCounts[i] = min(outCounts[i], g_coinStock[i]);
        }
        remaining -= outCounts[i] * DENOMINATIONS[i];
    }
}

// ============================================================================
//  printDenominationData() — log output matching original binary format
//  Strings "Split %d > FData : %s", "D[%d] :", " L:%d" confirmed in binary
// ============================================================================

void printDenominationData(int amount, int* counts) {
    char fdata[64] = {0};
    char tmp[16];
    bool first = true;
    for (int i = 0; i < DENOM_COUNT; i++) {
        if (counts[i] > 0) {
            if (!first) strcat(fdata, ",");
            snprintf(tmp, sizeof(tmp), "%dx%d", counts[i], DENOMINATIONS[i]);
            strcat(fdata, tmp);
            first = false;
        }
    }
    if (strlen(fdata) == 0) strcat(fdata, "none");

    Serial.printf("Split %d > FData : %s\n", amount, fdata);

    for (int i = 0; i < DENOM_COUNT; i++) {
        Serial.printf("D[%d] :\n", i);
        Serial.printf(" L:%d\n", counts[i]);
    }
}

// ============================================================================
//  canMakeChange() — verify we have enough coins before dispensing
// ============================================================================

bool canMakeChange(int amount) {
    int remaining = amount;
    for (int i = DENOM_COUNT - 1; i >= 0; i--) {
        int use = remaining / DENOMINATIONS[i];
        if (MAX_COINS_PER_DENOM > 0) use = min(use, g_coinStock[i]);
        remaining -= use * DENOMINATIONS[i];
    }
    if (remaining != 0) {
        Serial.printf("[WARN] Cannot make exact change for ₱%d (remainder: %d)\n",
                      amount, remaining);
        return false;
    }
    return true;
}

// ============================================================================
//  lookupBillValue() — map acceptor byte to peso value
//  TODO: sniff your actual bill acceptor serial output and update BILL_BYTE_TABLE
//        in config.h
// ============================================================================

int lookupBillValue(uint8_t byte) {
    for (int i = 0; i < BILL_TABLE_SIZE; i++) {
        if (BILL_BYTE_TABLE[i][0] == byte) {
            return BILL_BYTE_TABLE[i][1];
        }
    }
    return 0;  // unknown byte
}

// ============================================================================
//  lookupCoinValue() — map pulse count to peso value
//  TODO: verify pulse counts on actual coin acceptor hardware
// ============================================================================

int lookupCoinValue(int pulses) {
    for (int i = 0; i < COIN_PULSE_TABLE_SIZE; i++) {
        if (COIN_PULSE_TABLE[i][0] == pulses) {
            return COIN_PULSE_TABLE[i][1];
        }
    }
    return 0;  // unknown pulse count
}

// ============================================================================
//  uart_event_task — FreeRTOS task
//  Name confirmed in binary at 0x00010327
//  Reads bill acceptor data from UART2 and updates g_totalMoney
// ============================================================================

#if !DEBUG_MODE
void uart_event_task(void* pvParameters) {
    uart_event_t event;
    uint8_t      rxbuf[128];

    Serial.println("[uart_event_task] started");

    for (;;) {
        if (xQueueReceive(g_uart_queue, &event, portMAX_DELAY)) {
            switch (event.type) {

                case UART_DATA: {
                    int len = uart_read_bytes(BILL_UART_PORT, rxbuf,
                                              event.size, pdMS_TO_TICKS(100));
                    if (len <= 0) break;

                    Serial.printf("[UART] %d byte(s):", len);
                    for (int i = 0; i < len; i++) {
                        Serial.printf(" %02X", rxbuf[i]);
                    }
                    Serial.println();

                    // Try each byte as a bill code
                    for (int i = 0; i < len; i++) {
                        int value = lookupBillValue(rxbuf[i]);
                        if (value > 0) {
                            Serial.printf("[BILL] Accepted ₱%d\n", value);
                            g_totalMoney    += value;
                            g_exchangeReady  = true;
                            Serial.printf("Total Money: %d\n", g_totalMoney);
                        } else {
                            Serial.printf("[UART] Unknown byte 0x%02X — check BILL_BYTE_TABLE\n",
                                          rxbuf[i]);
                        }
                    }
                    break;
                }

                case UART_FIFO_OVF:
                case UART_BUFFER_FULL:
                    Serial.println("[UART] Buffer overflow — flushing");
                    uart_flush_input(BILL_UART_PORT);
                    xQueueReset(g_uart_queue);
                    break;

                case UART_BREAK:
                    Serial.println("[UART] Break signal");
                    break;

                case UART_PARITY_ERR:
                    Serial.println("[UART] Parity error — wrong baud rate?");
                    break;

                case UART_FRAME_ERR:
                    Serial.println("[UART] Frame error — wrong baud rate?");
                    break;

                default:
                    break;
            }
        }
    }
    vTaskDelete(NULL);
}
#else
// Stub so it compiles in DEBUG_MODE
void uart_event_task(void*) { vTaskDelete(NULL); }
#endif

// ============================================================================
//  DEBUG CONSOLE — Serial command interpreter
//  Only compiled when DEBUG_MODE 1
// ============================================================================

#if DEBUG_MODE
static String g_debugBuf = "";

void debugConsole() {
    while (Serial.available()) {
        char c = Serial.read();
        if (c == '\n' || c == '\r') {
            g_debugBuf.trim();
            if (g_debugBuf.length() > 0) {
                processDebugCommand(g_debugBuf);
            }
            g_debugBuf = "";
        } else {
            g_debugBuf += c;
        }
    }
}

void processDebugCommand(String cmd) {
    cmd.toUpperCase();

    if (cmd.startsWith("BILL ")) {
        int value = cmd.substring(5).toInt();
        debugSimulateBill(value);

    } else if (cmd.startsWith("COIN ")) {
        int value = cmd.substring(5).toInt();
        debugSimulateCoin(value);

    } else if (cmd == "EXCHANGE") {
        if (g_totalMoney > 0) {
            g_exchangeReady = true;
        } else {
            Serial.println("[DEBUG] No money inserted yet. Use BILL or COIN first.");
        }

    } else if (cmd == "STATUS") {
        Serial.printf("--- STATUS ---\n");
        Serial.printf("Total Money : ₱%d\n", g_totalMoney);
        Serial.printf("Exchange    : %s\n", g_exchangeReady ? "PENDING" : "idle");
        Serial.printf("Hopper      : %s\n", g_hopperRunning ? "RUNNING" : "stopped");
        Serial.printf("Coin stock  :\n");
        for (int i = 0; i < DENOM_COUNT; i++) {
            Serial.printf("  ₱%2d  x %d\n", DENOMINATIONS[i], g_coinStock[i]);
        }
        Serial.printf("--------------\n");

    } else if (cmd == "RESET") {
        g_totalMoney    = 0;
        g_exchangeReady = false;
        Serial.println("[DEBUG] State reset.");
        Serial.printf("Total Money: %d\n", g_totalMoney);

    } else if (cmd == "REFILL") {
        for (int i = 0; i < DENOM_COUNT; i++) g_coinStock[i] = MAX_COINS_PER_DENOM;
        Serial.println("[DEBUG] Coin stock refilled.");

    } else if (cmd == "HELP") {
        Serial.println("Commands:");
        Serial.println("  BILL <amount>   Simulate inserting a bill (e.g. BILL 100)");
        Serial.println("  COIN <amount>   Simulate inserting a coin (e.g. COIN 10)");
        Serial.println("  EXCHANGE        Manually trigger exchange");
        Serial.println("  STATUS          Show current state");
        Serial.println("  RESET           Reset totals");
        Serial.println("  REFILL          Refill simulated coin stock");

    } else {
        Serial.printf("[DEBUG] Unknown command: %s  (type HELP)\n", cmd.c_str());
    }
}

void debugSimulateBill(int value) {
    if (value < MIN_BILL_VALUE || value > MAX_BILL_VALUE) {
        Serial.printf("[DEBUG] Bill ₱%d rejected (range ₱%d–₱%d)\n",
                      value, MIN_BILL_VALUE, MAX_BILL_VALUE);
        return;
    }
    Serial.printf("[DEBUG] Bill ₱%d inserted\n", value);
    g_totalMoney    += value;
    g_exchangeReady  = true;
    Serial.printf("Total Money: %d\n", g_totalMoney);
}

void debugSimulateCoin(int value) {
    bool valid = false;
    for (int i = 0; i < DENOM_COUNT; i++) {
        if (DENOMINATIONS[i] == value) { valid = true; break; }
    }
    if (!valid) {
        Serial.printf("[DEBUG] ₱%d is not a known coin denomination\n", value);
        return;
    }
    Serial.printf("[DEBUG] Coin ₱%d inserted\n", value);
    g_totalMoney += value;
    Serial.printf("Total Money: %d\n", g_totalMoney);
}
#endif

