// ============================================================================
//  FORWARD DECLARATIONS
// ============================================================================

void openhop(int denomIndex);
void closehop(int denomIndex);
void closeAllHoppers();
bool exchangeMoney(int amount);
void exchangeTerminate();
void splitDenominations(int amount, int* outCounts);
void printDenominationData(int amount, int* counts);
bool canMakeChange(int amount);
int  lookupBillValue(uint8_t b);
int  lookupCoinValue(int pulses);

#if !DEBUG_MODE
void uart_event_task(void* pvParameters);
static QueueHandle_t g_uart_queue;
#endif

#if DEBUG_MODE
static String g_debugBuf = "";
void debugConsole();
void processDebugCommand(String cmd);
void debugSimulateBill(int value);
void debugSimulateCoin(int value);
#endif

// ============================================================================
//  setup()
// ============================================================================

void setup() {
    Serial.begin(115200);
    delay(200);

    Serial.println();
    Serial.println("SYSTEM START");
    Serial.println("Coinverge v1.0 | Build: Mar  5 2024 | IDF: v4.4.7");
    Serial.println("Hoppers: GPIO5=P1  GPIO18=P5  GPIO19=P10  GPIO17=P20");

#if DEBUG_MODE
    Serial.println("[DEBUG MODE] No GPIO. Use Serial commands. Type HELP.");
#else
    // ── Init all 4 hopper pins ───────────────────────────────
    for (int i = 0; i < DENOM_COUNT; i++) {
        int pin = HOPPER_MAP[i][1];
        pinMode(pin, OUTPUT);
        digitalWrite(pin, !HOP_ACTIVE);    // OFF at boot
    }

    // ── Hopper sensor ────────────────────────────────────────
    if (HOP_SENSOR_PIN >= 0) {
        pinMode(HOP_SENSOR_PIN, INPUT_PULLUP);
    }

    // ── Coin acceptor ────────────────────────────────────────
    if (COIN_PIN >= 0) {
        pinMode(COIN_PIN, INPUT_PULLUP);
    }

    // ── Bill acceptor UART ───────────────────────────────────
    Serial2.begin(BILL_UART_BAUD, SERIAL_8N1, BILL_UART_RX_PIN, BILL_UART_TX_PIN);
    xTaskCreate(uart_event_task, "uart_event_task", 4096, NULL, 12, NULL);
    Serial.println("[uart_event_task] started");
#endif

    // Init coin stock
    for (int i = 0; i < DENOM_COUNT; i++) {
        g_coinStock[i] = MAX_COINS_PER_HOPPER;
    }

    Serial.printf("Total Money: %d\n", g_totalMoney);
    Serial.println("Ready.");
}

// ============================================================================
//  loop() — Arduino loopTask (name confirmed in binary)
// ============================================================================

void loop() {
#if DEBUG_MODE
    debugConsole();
#else
    // ── Poll coin acceptor ───────────────────────────────────
    if (COIN_PIN >= 0) {
        static unsigned long lastPulseMs = 0;
        static unsigned int  pulseCount  = 0;
        static bool          inWindow    = false;

        if (digitalRead(COIN_PIN) == LOW) {
            unsigned long now = millis();
            if (now - lastPulseMs > COIN_DEBOUNCE_MS) {
                pulseCount++;
                lastPulseMs = now;
                inWindow    = true;
            }
        }

        if (inWindow && (millis() - lastPulseMs > COIN_WINDOW_MS)) {
            inWindow = false;
            int value = lookupCoinValue(pulseCount);
            Serial.printf("Count %u\n", pulseCount);
            pulseCount = 0;
            if (value > 0) {
                g_totalMoney += value;
                Serial.printf("Total Money: %d\n", g_totalMoney);
            } else {
                Serial.println("[WARN] Unknown coin pulse — ignored");
            }
        }
    }
#endif

    // ── Trigger exchange ─────────────────────────────────────
    if (g_exchangeReady && g_totalMoney > 0) {
        g_exchangeReady = false;
        if (!exchangeMoney(g_totalMoney)) {
            Serial.println("ERROR: NO EXCHANGE");
        }
    }

    delay(10);
}

// ============================================================================
//  openhop(denomIndex) — start one specific hopper
//  Original name "openhop" confirmed in binary at 0x00010180
// ============================================================================

void openhop(int denomIndex) {
    int pin   = HOPPER_MAP[denomIndex][1];
    int denom = HOPPER_MAP[denomIndex][0];
    Serial.printf("openhop [P%d → GPIO%d]\n", denom, pin);
#if !DEBUG_MODE
    digitalWrite(pin, HOP_ACTIVE);
#endif
}

// ============================================================================
//  closehop(denomIndex) — stop one specific hopper
//  Original name "closehop" confirmed in binary at 0x00010188
// ============================================================================

void closehop(int denomIndex) {
    int pin   = HOPPER_MAP[denomIndex][1];
    int denom = HOPPER_MAP[denomIndex][0];
    Serial.printf("closehop [P%d → GPIO%d]\n", denom, pin);
#if !DEBUG_MODE
    digitalWrite(pin, !HOP_ACTIVE);
#endif
}

void closeAllHoppers() {
    for (int i = 0; i < DENOM_COUNT; i++) {
        int pin = HOPPER_MAP[i][1];
#if !DEBUG_MODE
        digitalWrite(pin, !HOP_ACTIVE);
#endif
    }
}

// ============================================================================
//  exchangeMoney(amount) — main exchange logic
//  Name + "exchangeMoney: " confirmed in binary at 0x0001019f
// ============================================================================

bool exchangeMoney(int amount) {
    Serial.printf("exchangeMoney: %d\n", amount);

    if (amount <= 0) {
        Serial.println("ERROR: NO EXCHANGE");
        return false;
    }
    if (amount < MIN_BILL_VALUE || amount > MAX_BILL_VALUE) {
        Serial.printf("[WARN] Amount P%d outside range (P%d-P%d)\n",
                      amount, MIN_BILL_VALUE, MAX_BILL_VALUE);
        Serial.println("ERROR: NO EXCHANGE");
        return false;
    }
    if (!canMakeChange(amount)) {
        Serial.println("ERROR: NO EXCHANGE");
        return false;
    }

    // Calculate how many of each coin to dispense
    int counts[DENOM_COUNT] = {0};
    splitDenominations(amount, counts);
    printDenominationData(amount, counts);

    // ── Dispense each denomination independently ─────────────
    // Walk largest denomination first
    for (int i = DENOM_COUNT - 1; i >= 0; i--) {
        int need  = counts[i];
        int denom = HOPPER_MAP[i][0];
        if (need == 0) continue;

        Serial.printf("[HOP] Dispensing %d x P%d\n", need, denom);
        openhop(i);

#if DEBUG_MODE
        int ms = need * HOP_MS_PER_COIN;
        Serial.printf("[DEBUG] Simulating %d coins (%d ms)\n", need, ms);
        delay(min(ms, 3000));
        g_coinStock[i] -= need;

#else
        if (HOP_SENSOR_PIN >= 0) {
            // Sensor-counted dispensing — most accurate
            for (int c = 0; c < need; c++) {
                unsigned long start = millis();
                bool sensed = false;
                while (millis() - start < HOP_COIN_TIMEOUT_MS) {
                    if (digitalRead(HOP_SENSOR_PIN) == LOW) {
                        delay(20);
                        while (digitalRead(HOP_SENSOR_PIN) == LOW);
                        sensed = true;
                        break;
                    }
                    delay(5);
                }
                if (!sensed) {
                    Serial.printf("[ERROR] Sensor timeout: coin %d/%d P%d\n",
                                  c + 1, need, denom);
                    closehop(i);
                    closeAllHoppers();
                    exchangeTerminate();
                    return false;
                }
                g_coinStock[i]--;
            }
        } else {
            // Timed dispensing fallback
            delay(need * HOP_MS_PER_COIN);
            g_coinStock[i] -= need;
        }
#endif

        closehop(i);
    }

    exchangeTerminate();
    return true;
}

// ============================================================================
//  exchangeTerminate() — end transaction, reset total
//  Name confirmed in binary at 0x000101c2
// ============================================================================

void exchangeTerminate() {
    Serial.println("exchangeTerminate");
    closeAllHoppers();
    g_totalMoney    = 0;
    g_exchangeReady = false;
    Serial.printf("Total Money: %d\n", g_totalMoney);
}

// ============================================================================
//  splitDenominations() — greedy largest-first coin split
//  Derived from "Split %d > FData : %s" in binary at 0x00010154
// ============================================================================

void splitDenominations(int amount, int* outCounts) {
    int remaining = amount;
    for (int i = DENOM_COUNT - 1; i >= 0; i--) {
        int denom = HOPPER_MAP[i][0];
        outCounts[i] = remaining / denom;
        if (MAX_COINS_PER_HOPPER > 0) {
            outCounts[i] = min(outCounts[i], g_coinStock[i]);
        }
        remaining -= outCounts[i] * denom;
    }
}

// ============================================================================
//  printDenominationData() — matches original binary debug output format
//  "Split %d > FData : %s"  "D[%d] :"  " L:%d"
// ============================================================================

void printDenominationData(int amount, int* counts) {
    char fdata[64] = {0};
    char tmp[16];
    bool first = true;
    for (int i = 0; i < DENOM_COUNT; i++) {
        if (counts[i] > 0) {
            if (!first) strcat(fdata, ",");
            snprintf(tmp, sizeof(tmp), "%dx%d", counts[i], HOPPER_MAP[i][0]);
            strcat(fdata, tmp);
            first = false;
        }
    }
    if (strlen(fdata) == 0) strcat(fdata, "none");

    Serial.printf("Split %d > FData : %s\n", amount, fdata);
    for (int i = 0; i < DENOM_COUNT; i++) {
        Serial.printf("D[%d] :\n", i);
        Serial.printf(" L:%d\n", counts[i]);
    }
}

// ============================================================================
//  canMakeChange() — check stock before dispensing
// ============================================================================

bool canMakeChange(int amount) {
    int remaining = amount;
    for (int i = DENOM_COUNT - 1; i >= 0; i--) {
        int use = remaining / HOPPER_MAP[i][0];
        if (MAX_COINS_PER_HOPPER > 0) use = min(use, g_coinStock[i]);
        remaining -= use * HOPPER_MAP[i][0];
    }
    if (remaining != 0) {
        Serial.printf("[WARN] Cannot make exact change for P%d (remainder: %d)\n",
                      amount, remaining);
        return false;
    }
    return true;
}

// ============================================================================
//  lookupBillValue() — map UART byte to bill peso value
// ============================================================================

int lookupBillValue(uint8_t b) {
    for (int i = 0; i < BILL_TABLE_SIZE; i++) {
        if (BILL_BYTE_TABLE[i][0] == (int)b) return BILL_BYTE_TABLE[i][1];
    }
    return 0;
}

// ============================================================================
//  lookupCoinValue() — map pulse count to coin peso value
// ============================================================================

int lookupCoinValue(int pulses) {
    for (int i = 0; i < COIN_PULSE_TABLE_SIZE; i++) {
        if (COIN_PULSE_TABLE[i][0] == pulses) return COIN_PULSE_TABLE[i][1];
    }
    return 0;
}

// ============================================================================
//  uart_event_task — bill acceptor UART reader
//  Name confirmed in binary at 0x00010327
//  Uses Arduino Serial2 (simpler, no IDF headers needed)
// ============================================================================

#if !DEBUG_MODE
void uart_event_task(void* pvParameters) {
    for (;;) {
        if (Serial2.available()) {
            Serial.print("[UART] Bytes:");
            while (Serial2.available()) {
                uint8_t b = (uint8_t)Serial2.read();
                Serial.printf(" 0x%02X", b);
                int value = lookupBillValue(b);
                if (value > 0) {
                    Serial.printf(" → P%d bill accepted\n", value);
                    g_totalMoney    += value;
                    g_exchangeReady  = true;
                    Serial.printf("Total Money: %d\n", g_totalMoney);
                } else {
                    Serial.printf(" → unknown (update BILL_BYTE_TABLE)\n");
                }
            }
        }
        vTaskDelay(20 / portTICK_PERIOD_MS);
    }
    vTaskDelete(NULL);
}
#endif

// ============================================================================
//  DEBUG CONSOLE — Serial command interpreter
// ============================================================================

#if DEBUG_MODE
void debugConsole() {
    while (Serial.available()) {
        char c = Serial.read();
        if (c == '\n' || c == '\r') {
            g_debugBuf.trim();
            if (g_debugBuf.length() > 0) processDebugCommand(g_debugBuf);
            g_debugBuf = "";
        } else {
            g_debugBuf += c;
        }
    }
}

void processDebugCommand(String cmd) {
    cmd.toUpperCase();

    if (cmd.startsWith("BILL ")) {
        debugSimulateBill(cmd.substring(5).toInt());

    } else if (cmd.startsWith("COIN ")) {
        debugSimulateCoin(cmd.substring(5).toInt());

    } else if (cmd == "EXCHANGE") {
        if (g_totalMoney > 0) g_exchangeReady = true;
        else Serial.println("[DEBUG] No money inserted. Use BILL or COIN first.");

    } else if (cmd == "STATUS") {
        Serial.println("--- STATUS ---");
        Serial.printf("Total Money : P%d\n", g_totalMoney);
        Serial.printf("Exchange    : %s\n", g_exchangeReady ? "PENDING" : "idle");
        Serial.println("Coin stock  :");
        for (int i = 0; i < DENOM_COUNT; i++) {
            Serial.printf("  P%2d  GPIO%d  x%d\n",
                          HOPPER_MAP[i][0], HOPPER_MAP[i][1], g_coinStock[i]);
        }
        Serial.println("--------------");

    } else if (cmd == "RESET") {
        g_totalMoney    = 0;
        g_exchangeReady = false;
        Serial.println("[DEBUG] Reset.");
        Serial.printf("Total Money: %d\n", g_totalMoney);

    } else if (cmd == "REFILL") {
        for (int i = 0; i < DENOM_COUNT; i++) g_coinStock[i] = MAX_COINS_PER_HOPPER;
        Serial.println("[DEBUG] Coin stock refilled.");

    } else if (cmd == "HELP") {
        Serial.println("Commands:");
        Serial.println("  BILL <amount>   e.g. BILL 100");
        Serial.println("  COIN <amount>   e.g. COIN 10");
        Serial.println("  EXCHANGE        trigger exchange");
        Serial.println("  STATUS          show state + stock");
        Serial.println("  RESET           clear totals");
        Serial.println("  REFILL          refill coin stock");

    } else {
        Serial.printf("[DEBUG] Unknown: %s  (type HELP)\n", cmd.c_str());
    }
}

void debugSimulateBill(int value) {
    if (value < MIN_BILL_VALUE || value > MAX_BILL_VALUE) {
        Serial.printf("[DEBUG] P%d rejected (range P%d-P%d)\n",
                      value, MIN_BILL_VALUE, MAX_BILL_VALUE);
        return;
    }
    Serial.printf("[DEBUG] Bill P%d inserted\n", value);
    g_totalMoney    += value;
    g_exchangeReady  = true;
    Serial.printf("Total Money: %d\n", g_totalMoney);
}

void debugSimulateCoin(int value) {
    for (int i = 0; i < DENOM_COUNT; i++) {
        if (HOPPER_MAP[i][0] == value) {
            Serial.printf("[DEBUG] Coin P%d inserted\n", value);
            g_totalMoney += value;
            Serial.printf("Total Money: %d\n", g_totalMoney);
            return;
        }
    }
    Serial.printf("[DEBUG] P%d is not a known denomination\n", value);
}
#endif

